 * Reduced motion: opt out of every animation/transition above.
 * ------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
    transition: none !important;
    mix-blend-mode: normal !important;
  }

  .reveal-content {
    transition: none;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

